{"content":"#!/usr/bin/env python3
"""Sokoban puzzle solver using A* search over box pushes.

Reads a puzzle from /app/puzzle.txt and writes {"moves": "..."} to
/app/solution.json. Standard library only.
"""

import heapq
import json
import time
from collections import deque
from itertools import count

DIRS = {'U': (-1, 0), 'D': (1, 0), 'L': (0, -1), 'R': (0, 1)}
MOVES = ('U', 'D', 'L', 'R')


def parse_puzzle(filename):
    """Read puzzle file and return puzzle string."""
    with open(filename, 'r') as f:
        return f.read()


def parse_map(puzzle_str):
    """Parse Sokoban map symbols and extract game state.

    Returns (player_pos, boxes, targets, walls).
    """
    lines = puzzle_str.split('\n')
    # Drop a single trailing empty line from a final newline, keep the rest.
    if lines and lines[-1] == '':
        lines.pop()
    # Strip carriage returns; drop lines only if the whole map is empty.
    lines = [ln.replace('\r', '') for ln in lines]
    if not lines or all(ln == '' for ln in lines):
        return None, set(), set(), set()

    h = len(lines)
    w = max(len(ln) for ln in lines)
    # Pad short rows with walls (missing cells are not floor).
    grid = []
    for ln in lines:
        grid.append(ln + '#' * (w - len(ln)))

    player_pos = None
    boxes = set()
    targets = set()
    walls = set()
    for r in range(h):
        for c in range(w):
            ch = grid[r][c]
            if ch == '#':
                walls.add((r, c))
            elif ch == '@':
                player_pos = (r, c)
            elif ch == '+':
                player_pos = (r, c)
                targets.add((r, c))
            elif ch == '$':
                boxes.add((r, c))
            elif ch == '*':
                boxes.add((r, c))
                targets.add((r, c))
            elif ch == '.':
                targets.add((r, c))
            elif ch == ' ':
                pass
            else:
                # Any unknown symbol is impassable.
                walls.add((r, c))

    # Cells of floor (' ') on the outside of the map (reachable from the
    # border through non-wall cells) are void, not playable floor.
    outside = set()
    queue = deque()
    for r in range(h):
        for c in range(w):
            if (r == 0 or r == h - 1 or c == 0 or c == w - 1):
                if (r, c) not in walls and (r, c) not in outside:
                    outside.add((r, c))
                    queue.append((r, c))
    while queue:
        r, c = queue.popleft()
        for dr, dc in DIRS.values():
            nb = (r + dr, c + dc)
            if 0 <= nb[0] < h and 0 <= nb[1] < w:
                if nb not in walls and nb not in outside:
                    outside.add(nb)
                    queue.append(nb)
    walls |= outside

    return player_pos, boxes, targets, walls


def try_move(player_pos, boxes, walls, direction):
    """Attempt to move player in specified direction.

    Returns (new_player_pos, new_boxes) if valid, None if invalid.
    """
    if player_pos is None or direction not in DIRS:
        return None
    dr, dc = DIRS[direction]
    new_player = (player_pos[0] + dr, player_pos[1] + dc)
    if new_player in walls:
        return None
    if new_player in boxes:
        new_box = (new_player[0] + dr, new_player[1] + dc)
        if new_box in walls or new_box in boxes:
            return None
        new_boxes = set(boxes)
        new_boxes.discard(new_player)
        new_boxes.add(new_box)
        return new_player, new_boxes
    return new_player, set(boxes)


def _hungarian(cost):
    """Minimum assignment cost for an n x m matrix (n <= m)."""
    n = len(cost)
    if n == 0:
        return 0
    m = len(cost[0])
    u = [0] * (n + 1)
    v = [0] * (m + 1)
    p = [0] * (m + 1)
    way = [0] * (m + 1)
    for i in range(1, n + 1):
        p[0] = i
        j0 = 0
        minv = [float('inf')] * (m + 1)
        used = [False] * (m + 1)
        while True:
            used[j0] = True
            i0 = p[j0]
            delta = float('inf')
            j1 = 0
            row = cost[i0 - 1]
            for j in range(1, m + 1):
                if used[j]:
                    continue
                cur = row[j - 1] - u[i0] - v[j]
                if cur < minv[j]:
                    minv[j] = cur
                    way[j] = j0
                if minv[j] < delta:
                    delta = minv[j]
                    j1 = j
            for j in range(m + 1):
                if used[j]:
                    u[p[j]] += delta
                    v[j] -= delta
                else:
                    minv[j] -= delta
            j0 = j1
            if p[j0] == 0:
                break
        while j0:
            j1 = way[j0]
            p[j0] = p[j1]
            j0 = j1
    return -v[0]


def _compute_dead_squares(walls, targets, h, w):
    """Static dead squares: floor cells a box can never leave to a target."""
    def blocked(cell, extra):
        r, c = cell
        return (r < 0 or r >= h or c < 0 or c >= w
                or cell in walls or cell in extra)

    floor = {(r, c) for r in range(h) for c in range(w)
             if (r, c) not in walls}
    cand = floor - targets
    dead = set()
    changed = True
    while changed:
        changed = False
        # Corner rule: two perpendicular blocked sides.
        for (r, c) in cand:
            if (r, c) in dead:
                continue
            up = blocked((r - 1, c), dead)
            dn = blocked((r + 1, c), dead)
            lf = blocked((r, c - 1), dead)
            rt = blocked((r, c + 1), dead)
            if (up and lf) or (up and rt) or (dn and lf) or (dn and rt):
                dead.add((r, c))
                changed = True
        # Wall-run rule: a floor run fully along blocked cells on one
        # side with no target in it can never be left.
        for r in range(h):
            run = []
            for c in range(w + 1):
                cell = (r, c)
                if c < w and cell in floor:
                    run.append(cell)
                else:
                    if run:
                        if not any(cell in targets for cell in run):
                            along = (
                                all(blocked((r - 1, c), dead) for _, c in run)
                                or all(blocked((r + 1, c), dead)
                                       for _, c in run)
                            )
                            if along:
                                for cell in run:
                                    if cell in cand and cell not in dead:
                                        dead.add(cell)
                                        changed = True
                        run = []
        for c in range(w):
            run = []
            for r in range(h + 1):
                cell = (r, c)
                if r < h and cell in floor:
                    run.append(cell)
                else:
                    if run:
                        if not any(cell in targets for cell in run):
                            along = (
                                all(blocked((rr, c - 1), dead) for rr, _ in run)
                                or all(blocked((rr, c + 1), dead)
                                       for rr, _ in run)
                            )
                            if along:
                                for cell in run:
                                    if cell in cand and cell not in dead:
                                        dead.add(cell)
                                        changed = True
                        run = []
    return dead


def _frozen_2x2(box, boxes, walls, targets):
    """True if box is stuck in a 2x2 wall/box block holding no box-on-target."""
    r, c = box
    for dr in (-1, 0):
        for dc in (-1, 0):
            cells = [(r + dr + i, c + dc + j) for i in (0, 1) for j in (0, 1)]
            if box not in cells:
                continue
            if all(cell in walls or cell in boxes for cell in cells):
                if not any(cell in boxes and cell in targets for cell in cells):
                    return True
    return False


def _reachable(player, boxes, walls):
    """BFS of player-reachable cells; returns parent map {cell: (prev, move)}."""
    parents = {player: (None, '')}
    queue = deque([player])
    while queue:
        cur = queue.popleft()
        for mv in MOVES:
            dr, dc = DIRS[mv]
            nb = (cur[0] + dr, cur[1] + dc)
            if nb in parents or nb in walls or nb in boxes:
                continue
            parents[nb] = (cur, mv)
            queue.append(nb)
    return parents


def _walk_path(parents, dest):
    chars = []
    cur = dest
    while True:
        prev, mv = parents[cur]
        if prev is None:
            break
        chars.append(mv)
        cur = prev
    return ''.join(reversed(chars))


def solve(puzzle_str, time_limit=30.0, max_expansions=600000):
    """Solve a Sokoban puzzle; return a move string ("" if solved/unsolvable)."""
    if puzzle_str is None:
        return ""
    player, boxes, targets, walls = parse_map(puzzle_str)
    if player is None:
        return ""
    if not boxes or boxes <= targets:
        return ""
    if len(boxes) > len(targets):
        return ""
    if not targets:
        return ""

    h = max([r for r, _ in walls] + [player[0]]) + 1
    w = max([c for _, c in walls] + [player[1]]) + 1
    dead = _compute_dead_squares(walls, targets, h, w)
    if any(b in dead for b in boxes):
        return ""

    target_list = list(targets)
    heur_cache = {}

    def heuristic(frozen_boxes):
        hval = heur_cache.get(frozen_boxes)
        if hval is None:
            cost = [[abs(b[0] - t[0]) + abs(b[1] - t[1]) for t in target_list]
                    for b in frozen_boxes]
            hval = _hungarian(cost)
            heur_cache[frozen_boxes] = hval
        return hval

    start_boxes = frozenset(boxes)
    start_reach = _reachable(player, boxes, walls)
    start_key = (min(start_reach), start_boxes)

    g_score = {start_key: 0}
    parents = {start_key: (None, '')}
    counter = count()
    heap = [(heuristic(start_boxes), 0, next(counter), player, start_boxes)]

    expansions = 0
    deadline = time.time() + time_limit
    box_list_state = None

    while heap:
        if time.time() > deadline or expansions >= max_expansions:
            return ""
        _f, pushes, _, cur_player, cur_boxes = heapq.heappop(heap)
        cur_boxes_set = set(cur_boxes)
        reach = _reachable(cur_player, cur_boxes_set, walls)
        canon = min(reach)
        key = (canon, cur_boxes)
        if pushes > g_score.get(key, float('inf')):
            continue
        expansions += 1
        if cur_boxes_set <= targets:
            box_list_state = key
            break
        for box in cur_boxes:
            for mv in MOVES:
                dr, dc = DIRS[mv]
                behind = (box[0] - dr, box[1] - dc)
                ahead = (box[0] + dr, box[1] + dc)
                if behind not in reach:
                    continue
                if ahead in walls or ahead in cur_boxes_set:
                    continue
                if ahead in dead:
                    continue
                new_set = set(cur_boxes_set)
                new_set.discard(box)
                new_set.add(ahead)
                if _frozen_2x2(ahead, new_set, walls, targets):
                    continue
                new_frozen = frozenset(new_set)
                # Canonical key uses the push origin (player ends there);
                # canonicalize via its reachable region minimum.
                tmp_reach = _reachable(box, new_set, walls)
                new_key = (min(tmp_reach), new_frozen)
                new_pushes = pushes + 1
                if new_pushes >= g_score.get(new_key, float('inf')):
                    continue
                g_score[new_key] = new_pushes
                seg = _walk_path(reach, behind) + mv
                parents[new_key] = (key, seg)
                heapq.heappush(heap, (new_pushes + heuristic(new_frozen),
                                      new_pushes, next(counter), box,
                                      new_frozen))

    if box_list_state is None:
        return ""

    # Reconstruct full move sequence.
    segs = []
    key = box_list_state
    while parents[key][0] is not None:
        prev, seg = parents[key]
        segs.append(seg)
        key = prev
    moves = ''.join(reversed(segs))

    # Verify by simulation before returning.
    sim_player, sim_boxes = player, set(boxes)
    for mv in moves:
        res = try_move(sim_player, sim_boxes, walls, mv)
        if res is None:
            return ""
        sim_player, sim_boxes = res
    if not sim_boxes <= targets:
        return ""
    return moves


def main():
    puzzle_str = parse_puzzle('/app/puzzle.txt')
    moves = solve(puzzle_str)
    with open('/app/solution.json', 'w') as f:
        json.dump({"moves": moves}, f)


if __name__ == '__main__':
    main()
